    }

    // USER 2: Standard User (Salesforce Full License - 2 of 2)
    if(profileMap.containsKey('Standard User')) {
        newUsers.add(new User(
            FirstName = 'Test',
            LastName = 'Standard',
            Email = 'standard@flowstral.test',
            Username = 'standard@flowstral.test.' + orgId,
            Alias = 'tstd',
            ProfileId = profileMap.get('Standard User'),
            UserRoleId = roleMap.get('Flowstral_Test_Sales_Manager'),
            TimeZoneSidKey = 'America/Los_Angeles',
            LocaleSidKey = 'en_US',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            IsActive = true
        ));
        System.debug('Adding Standard user (Salesforce Full license)');
    }

    // USER 3: Platform User (Salesforce Platform License - 1 of 6)
    if(profileMap.containsKey('Standard Platform User')) {
        newUsers.add(new User(
            FirstName = 'Test',
            LastName = 'Platform',
            Email = 'platform@flowstral.test',
            Username = 'platform@flowstral.test.' + orgId,
            Alias = 'tplat',
            ProfileId = profileMap.get('Standard Platform User'),
            UserRoleId = roleMap.get('Flowstral_Test_VP_Sales'),
