    if(profileMap.containsKey('Chatter Free User')) {
        newUsers.add(new User(
            FirstName = 'Test',
            LastName = 'Chatter',
            Email = 'chatter@flowstral.test',
            Username = 'chatter@flowstral.test.' + orgId,
            Alias = 'tchat',
            ProfileId = profileMap.get('Chatter Free User'),
            // Note: Chatter Free users cannot have roles
            TimeZoneSidKey = 'America/Los_Angeles',
            LocaleSidKey = 'en_US',
            EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US',
            IsActive = true
        ));
        System.debug('Adding Chatter user (Chatter Free license)');
    }

    if(!newUsers.isEmpty()) {
        insert newUsers;
        System.debug('SUCCESS: Created ' + newUsers.size() + ' test users');
        System.debug('License usage: 2 Salesforce Full, 1 Platform, 1 Chatter Free');
    }
} else {
    System.debug('Test users already exist: ' + existingUsers.size());
}

// Assign Permission Sets to Test Users
List<User> testUsers = [SELECT Id, Username, Profile.Name FROM User WHERE Username LIKE '%flowstral.test%' AND IsActive = true];
List<PermissionSet> testPS = [SELECT Id, Name FROM PermissionSet WHERE Name LIKE 'Flowstral_Test%'];

if(!testUsers.isEmpty() && !testPS.isEmpty()) {
    // Check existing assignments
    Set<String> existingAssignments = new Set<String>();
    for(PermissionSetAssignment psa : [SELECT AssigneeId, PermissionSetId FROM PermissionSetAssignment WHERE AssigneeId IN :testUsers]) {
        existingAssignments.add(psa.AssigneeId + '-' + psa.PermissionSetId);
    }

    List<PermissionSetAssignment> newAssignments = new List<PermissionSetAssignment>();

    for(User u : testUsers) {
        // Admin gets all permission sets
        if(u.Username.contains('admin@')) {
            for(PermissionSet ps : testPS) {
                String key = u.Id + '-' + ps.Id;
                if(!existingAssignments.contains(key)) {
                    newAssignments.add(new PermissionSetAssignment(AssigneeId = u.Id, PermissionSetId = ps.Id));
                }
            }
        }
        // Standard user gets Edit + API access
        if(u.Username.contains('standard@')) {
            for(PermissionSet ps : testPS) {
                if(ps.Name.contains('Edit_Access') || ps.Name.contains('API_Access')) {
                    String key = u.Id + '-' + ps.Id;
                    if(!existingAssignments.contains(key)) {
                        newAssignments.add(new PermissionSetAssignment(AssigneeId = u.Id, PermissionSetId = ps.Id));
                    }
                }
            }
        }
        // Platform user gets Read Only + Edit access
        if(u.Username.contains('platform@')) {
            for(PermissionSet ps : testPS) {
                if(ps.Name.contains('Read_Only') || ps.Name.contains('Edit_Access')) {
                    String key = u.Id + '-' + ps.Id;
                    if(!existingAssignments.contains(key)) {
                        newAssignments.add(new PermissionSetAssignment(AssigneeId = u.Id, PermissionSetId = ps.Id));
                    }
                }
            }
        }
        // Chatter user gets Read Only only
        if(u.Username.contains('chatter@')) {
            for(PermissionSet ps : testPS) {
                if(ps.Name.contains('Read_Only')) {
                    String key = u.Id + '-' + ps.Id;
                    if(!existingAssignments.contains(key)) {
                        newAssignments.add(new PermissionSetAssignment(AssigneeId = u.Id, PermissionSetId = ps.Id));
                    }
                }
            }
        }
    }

    if(!newAssignments.isEmpty()) {
        insert newAssignments;
        System.debug('Created ' + newAssignments.size() + ' permission set assignments');
    } else {
        System.debug('All assignments already exist');
    }
}
